import java.util.*;class MedianFinder{PriorityQueue<Integer>lo=new PriorityQueue<>(Collections.reverseOrder()),hi=new PriorityQueue<>();public MedianFinder(){}public void addNum(int x){if(lo.isEmpty()||x<=lo.peek())lo.add(x);else hi.add(x);if(lo.size()>hi.size()+1)hi.add(lo.remove());else if(hi.size()>lo.size())lo.add(hi.remove());}public double findMedian(){return lo.size()==hi.size()?((double)lo.peek()+hi.peek())/2:lo.peek();}}
